cpp_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>

void l2norm_fp16_launcher(const at::Tensor& input, at::Tensor& output);

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("l2norm_fp16", &l2norm_fp16_launcher, "L2Norm fp16 (CUDA)");
}
'''

cuda_source = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_fp16.h>

template <int BLOCK_SIZE>
__global__ void l2norm_fp16_kernel(const half* __restrict__ input,
                                   half* __restrict__ output,
                                   const int64_t batch,
                                   const int64_t dim) {
    extern __shared__ float sdata[];
    int64_t row = blockIdx.x;
    const half* row_in  = input  + row * dim;
    half*       row_out = output + row * dim;

    // ---- first pass: compute sum of squares ----
    float sum = 0.0f;
    for (int64_t i = threadIdx.x; i < dim; i += BLOCK_SIZE) {
        half h = row_in[i];
        float v = __half2float(h);
        sum += v * v;
    }
    // reduction in shared memory
    sdata[threadIdx.x] = sum;
    __syncthreads();

    // reduce within block
    for (int stride = BLOCK_SIZE / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
        }
        __syncthreads();
    }

    float norm = sqrtf(sdata[0] + 1e-12f); // epsilon to avoid div by zero
    float inv_norm = __fdividef(1.0f, norm);

    // ---- second pass: write normalized values ----
    for (int64_t i = threadIdx.x; i < dim; i += BLOCK_SIZE) {
        half h = row_in[i];
        float v = __half2float(h);
        float vn = v * inv_norm;
        row_out[i] = __float2half(vn);
    }
}

// launcher
void l2norm_fp16_launcher(const at::Tensor& input, at::Tensor& output) {
    const int64_t batch = input.size(0);
    const int64_t dim   = input.size(1);
    const int threads = 256;
    const dim3 blocks(batch);
    const size_t shmem = threads * sizeof(float);

    AT_DISPATCH_HALF_TYPES(input.scalar_type(), "l2norm_fp16_kernel", ([&] {
        l2norm_fp16_kernel<threads><<<blocks, threads, shmem, at::cuda::getCurrentCUDAStream()>>>(
            input.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            batch,
            dim);
    }));

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        printf("CUDA error in l2norm_fp16_kernel: %s\\n", cudaGetErrorString(err));
    }
}
'''

# Compile the extension
l2norm_ext = load_inline(name='l2norm_ext',
                         cpp_sources=cpp_source,
                         cuda_sources=cuda_source,
                         functions=['l2norm_fp16'],
                         verbose=False)

# ----------------------------------------------------------------------
# Autograd Function
# ----------------------------------------------------------------------
class L2NormFunction(torch.autograd.Function):
    @staticmethod
    def forward(ctx, x):
        # Ensure half precision and contiguous
        x_half = x.to(torch.float16).contiguous()
        out = torch.empty_like(x_half)
        l2norm_ext.l2norm_fp16(x_half, out)
        return out

    @staticmethod
    def backward(ctx, grad_output):
        # Simple pass‑through gradient (not used in the reference)
        return grad_output

# ----------------------------------------------------------------------
# Model using the custom kernel
# ----------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Same functionality as the reference Model but uses a custom CUDA kernel.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return L2NormFunction.apply(x)

# ----------------------------------------------------------------------
# Helper functions matching the reference API
# ----------------------------------------------------------------------
def get_inputs():
    batch_size = 32768
    dim = 65535
    x = torch.rand(batch_size, dim, dtype=torch.float16, device='cuda')
    return [x]

def get_init_inputs():
    return []

# ----------------------------------------------------------------------
# Simple sanity check (optional, can be removed in production)
# ----------------------------------------------------------------------
if __name__ == "__main__":
    model = ModelNew().cuda()
    x = torch.rand(4, 8, device='cuda')
    y = model(x)
    # compare with PyTorch built‑in
    y_ref = x / torch.norm(x, p=2, dim=1, keepdim=True)
    print(torch.allclose(y, y_ref, atol=1e-3, rtol=1e-3))
